package com.example.maven.plugin;

import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.plugin.MojoFailureException;
import org.apache.maven.plugins.annotations.Mojo;
import org.apache.maven.plugins.annotations.Parameter;
import org.apache.maven.project.MavenProject;

import java.util.Map;
import java.util.TreeMap;

/**
 * A Mojo to list all system environment variables.
 * This plugin iterates through all environment variables and displays them.
 */
@Mojo(name = "list-env", requiresProject = false, threadSafe = true)
public class ListEnvVarsMojo extends AbstractMojo {

    /**
     * The Maven project object.
     */
    @Parameter(defaultValue = "${project}", readonly = true)
    private MavenProject project;

    /**
     * If true, sorts environment variables alphabetically.
     */
    @Parameter(property = "sort", defaultValue = "true")
    private boolean sort;

    /**
     * If provided, only shows environment variables that contain this text (case insensitive).
     */
    @Parameter(property = "filter")
    private String filter;

    /**
     * Executes the mojo to list environment variables.
     * 
     * @throws MojoExecutionException if an unexpected error occurs
     * @throws MojoFailureException if a user error occurs
     */
    public void execute() throws MojoExecutionException, MojoFailureException {
        getLog().info("Listing system environment variables...");
        getLog().info("");

        // Get all environment variables
        Map<String, String> envVars = System.getenv();

        // Apply sorting if requested
        Map<String, String> processedEnvVars = envVars;
        if (sort) {
            processedEnvVars = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
            processedEnvVars.putAll(envVars);
        }

        int displayedCount = 0;
        int totalCount = envVars.size();

        // Display each environment variable
        for (Map.Entry<String, String> entry : processedEnvVars.entrySet()) {
            String key = entry.getKey();
            String value = entry.getValue();

            // Apply filter if specified
            if (filter != null && !filter.isEmpty()) {
                if (!(key.toLowerCase().contains(filter.toLowerCase()) || 
                      (value != null && value.toLowerCase().contains(filter.toLowerCase())))) {
                    continue;
                }
            }

            // Display the environment variable
            getLog().info(key + " = " + (value != null ? value : ""));
            displayedCount++;
        }

        // Summary
        if (filter != null && !filter.isEmpty()) {
            getLog().info("");
            getLog().info(String.format("Displayed %d of %d environment variables (filtered by '%s')", 
                                     displayedCount, totalCount, filter));
        } else {
            getLog().info("");
            getLog().info(String.format("Listed %d environment variables", displayedCount));
        }

        // Also store as a project property for potential use in other plugins
        project.getProperties().setProperty("env.var.count", String.valueOf(displayedCount));
    }
}

